import { z } from 'zod'

import { PAGINATION } from '../constants/pagination'

/**
 * Entity identifier: every SyncSpace ID is a UUID (v7, generated by the database).
 * Validating the format at the boundary turns malformed IDs into a 400 instead of
 * a PostgreSQL `uuid` cast error. Clients should still treat IDs as opaque.
 */
export const idSchema = z.uuid()

export const isoDateTimeSchema = z.iso.datetime({ offset: true })

/** Query-string input for cursor-paginated list endpoints. */
export const cursorPaginationQuerySchema = z.object({
  cursor: z.string().min(1).optional(),
  limit: z.coerce.number().int().min(1).max(PAGINATION.MAX_LIMIT).default(PAGINATION.DEFAULT_LIMIT),
})

export type CursorPaginationQuery = z.infer<typeof cursorPaginationQuerySchema>

/** Builds the response schema for a cursor-paginated list of `item`. */
export function cursorPageSchema<TItem extends z.ZodType>(item: TItem) {
  return z.object({
    items: z.array(item),
    nextCursor: z.string().nullable(),
  })
}
